module Top( input clk, rst, output [7:0] leds
); reg [23:0] reg_0; always @(posedge clk) begin if (rst) reg_0 <= 24'h0; else reg_0 <= reg_0 + 24'h1; end // always @(posedge) assign leds = reg_0[23:16];
endmodule

