Modules can be parameterised by specifying a list of parameters surrounded by < and > after the module name. module Adder<N: uint>( a: uint<N>, b: uint<N>, carry_in: bool,
) -> ( sum: uint<N>, carry_out: bool,
) { let carry_chain: bool[N + 1] carry_chain[0] = carry_in let bits: bool[N] for i in 0..<N { FullAdder( a: a[i], b: b[i], carry_in: carry_chain[i], carry_out: carry_chain[i + 1], sum: bits[i], ) } carry_out = carry_chain[N] sum = uint(bits)
} # module Top() -> () {}

