module Counter(clk: clock, enable: bool) -> (value: uint<8>) { let counter = Reg<uint<8>>(clk, en: enable) counter.d = counter.q + 1'b1 value = counter.q
} The register only updates its value when enable is asserted. The same behaviour can be obtained using the d port only: module Counter(clk: clock, enable: bool) -> (value: uint<8>) { let counter = Reg<uint<8>>(clk) counter.d = enable ? counter.q + 1'b1 : counter.q value = counter.q
}

